WITH filtered_order_items AS (SELECT * FROM order_items WHERE (product_id IN (4, 24) AND product_id IN (27, 39)) OR quantity BETWEEN 3 AND 5), quantity_bucket_summary AS (SELECT CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 5 THEN 'mid' ELSE 'low' END AS quantity_bucket, ROUND(AVG(quantity), 2) AS avg_quantity, SUM(quantity * unit_price) AS revenue FROM filtered_order_items GROUP BY CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 5 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, avg_quantity, revenue FROM quantity_bucket_summary WHERE revenue > 51;
